    "contrainte_regence": {
      "pourquoi": "Tu tiens la place de quelqu'un qui reviendra s'y asseoir. Tout ce que tu prepares est bon ; ce qui engage pour toujours ne t'appartient pas.",
      "interdits": [
        {
          "quoi": "prêter ou rompre un serment, un hommage, une allégeance",
          "a_la_place": "préparer la forme du serment, réunir les témoins, fixer une date — et laisser la parole elle-même au retour de qui tient le siège"
        },
        {
          "quoi": "conclure un mariage, des fiançailles, promettre une main",
          "a_la_place": "sonder, chiffrer la dot, écrire le projet au registre — aucune promesse donnée, aucun contrat scellé"
        },
        {
          "quoi": "livrer bataille, donner l'assaut, engager le combat",
          "a_la_place": "poster, reconnaître, chiffrer les forces, tenir la position — le premier coup n'est pas de son ressort"
        },
        {
          "quoi": "faire tuer, exécuter, mettre à mort",
          "a_la_place": "arrêter, garder au cachot, instruire, écrire le chef d'accusation — la sentence attend qui tient le siège"
        },
        {
          "quoi": "déclarer une trahison, changer de camp, livrer quelqu'un",
          "a_la_place": "recueillir, vérifier, écrire ce qu'on soupçonne et à qui on le doit — l'accusation publique attend"
        },
        {
          "quoi": "se rendre, capituler, déposer les armes",
          "a_la_place": "tenir, compter les vivres et les bras, ouvrir un pourparler qui n'engage rien — et le dire tel quel"
        },
        {
          "quoi": "céder, livrer ou ouvrir une place forte",
          "a_la_place": "barrer, doubler le guet, préparer l'évacuation des gens — les clefs ne quittent pas la maison"
